html:
{#- The desk's copy of the dashboard's payslip (client/src/lib/payslipdoc.js):
    the same layout, so a slip printed or emailed from ERPNext reads the same as
    one printed from Payroll → Payslips. Every figure is the slip's own — gross,
    deductions and net are what hrms stored, nothing is added up here. -#}
<style>
	.mp { font: 13px/1.45 Calibri, Arial, sans-serif; color: #1f2937; }
	.mp .head { text-align: center; border-bottom: 2px solid #374151; padding-bottom: 6px; margin-bottom: 8px; position: relative; }
	.mp .head h1 { margin: 0; font-size: 18px; }
	.mp .head .m { color: #6b7280; font-size: 12px; }
	.mp .draft { position: absolute; right: 0; top: 0; color: #b45309; border: 1px solid #b45309; padding: 0 6px; font-size: 11px; }
	.mp .title { text-align: center; font-weight: 700; margin: 6px 0; letter-spacing: .5px; }
	.mp table { width: 100%; border-collapse: collapse; }
	.mp .who td { padding: 2px 6px; vertical-align: top; }
	.mp .who td.k { color: #6b7280; width: 18%; }
	.mp .pay { margin-top: 8px; }
	.mp .pay th { background: #374151; color: #fff; text-align: left; padding: 4px 6px; }
	.mp .pay td { border-bottom: 1px solid #e5e7eb; padding: 3px 6px; }
	.mp .pay .a { text-align: right; }
	.mp .pay td.sep { border-left: 1px solid #d1d5db; }
	.mp .pay tr.tot td { font-weight: 700; border-top: 2px solid #9ca3af; background: #f3f4f6; }
	.mp .net { margin: 10px 0 2px; padding: 6px 8px; background: #e2efda; font-size: 15px; font-weight: 700; }
	.mp .net span { float: right; }
	.mp .words { color: #4b5563; font-size: 12px; }
	.mp .foot { margin-top: 14px; color: #6b7280; font-size: 11px; }
</style>
{%- set co = frappe.get_cached_doc("Company", doc.company) if doc.company else None -%}
{%- set code = frappe.db.get_value("Employee", doc.employee, "employee_number") or doc.employee -%}
{#- hrms puts an Absent day in absent_days and leave without pay in its own
    field; the person lost both, so the slip shows the sum (lib/payroll.js lossOfPay). -#}
{%- set lop = (doc.absent_days or 0) + (doc.leave_without_pay or 0) -%}
{#- A line hrms keeps only for its arithmetic is not something the person was paid. -#}
{%- set earnings = doc.earnings | rejectattr("statistical_component") | rejectattr("do_not_include_in_total") | list -%}
{%- set deductions = doc.deductions | rejectattr("statistical_component") | rejectattr("do_not_include_in_total") | list -%}
{%- set rows = [earnings | length, deductions | length] | max -%}
<div class="mp">
	<div class="head">
		{% if doc.docstatus == 0 %}<span class="draft">DRAFT</span>{% endif %}
		<h1>{{ doc.company or "" }}</h1>
		{%- if co %}
		<div class="m">{{ [co.tax_id and ("GSTIN/Tax ID: " ~ co.tax_id), co.phone_no and ("Phone: " ~ co.phone_no), co.email] | select | join("  ·  ") }}</div>
		{%- endif %}
	</div>
	<div class="title">PAYSLIP — {{ frappe.utils.getdate(doc.start_date).strftime("%B %Y").upper() }}</div>
	<table class="who">
		<tr><td class="k">Employee</td><td>{{ doc.employee_name or "" }}</td><td class="k">Code</td><td>{{ code }}</td></tr>
		<tr><td class="k">Designation</td><td>{{ doc.designation or "" }}</td><td class="k">Department</td><td>{{ doc.department or "" }}</td></tr>
		<tr><td class="k">Pay days</td><td>{{ doc.payment_days or "" }}</td><td class="k">Loss of pay days</td><td>{{ lop or "" }}</td></tr>
	</table>
	<table class="pay">
		<thead><tr><th>Earnings</th><th class="a">₹</th><th>Deductions</th><th class="a">₹</th></tr></thead>
		<tbody>
			{%- for i in range(rows) %}
			{%- set e = earnings[i] if i < earnings | length else None %}
			{%- set d = deductions[i] if i < deductions | length else None %}
			<tr>
				<td>{{ e.salary_component if e else "" }}</td>
				<td class="a">{{ frappe.utils.fmt_money(e.amount, 2) if e else "" }}</td>
				<td class="sep">{{ d.salary_component if d else "" }}</td>
				<td class="a">{{ frappe.utils.fmt_money(d.amount, 2) if d else "" }}</td>
			</tr>
			{%- endfor %}
			<tr class="tot">
				<td>Gross pay</td><td class="a">{{ frappe.utils.fmt_money(doc.gross_pay, 2) }}</td>
				<td class="sep">Total deductions</td><td class="a">{{ frappe.utils.fmt_money(doc.total_deduction, 2) }}</td>
			</tr>
		</tbody>
	</table>
	<div class="net">Net pay <span>₹ {{ frappe.utils.fmt_money(doc.net_pay, 2) }}</span></div>
	<div class="words">{{ frappe.utils.money_in_words(doc.net_pay, "INR") }}</div>
	<div class="foot">This is a computer-generated payslip.</div>
</div>
